{
  "contents": [
    {
      "parts": [
        {
          "text": "Act as a Senior SOC Lead. Analyze the following security incident and provide a 2-sentence summary and one suggested MITRE D3FEND countermeasure. Short Description: {{action.short_description}}"
        }
      ]
    }
  ]
}

sys_variable_value.value:
(function execute(inputs, outputs) {
  try {
        var response = JSON.parse(inputs.raw_response);

        // This path drills down into the Gemini 3.1 JSON structure
        if (response.candidates && response.candidates.length > 0) {
            outputs.analysis = response.candidates[0].content.parts[0].text;
        } else if (response.error) {
            outputs.analysis = "API Error: " + response.error.message;
        } else {
            outputs.analysis = "No analysis returned. Check REST logs.";
        }
    } catch (e) {
        outputs.analysis = "Parse Error: " + e.message;
    }
})(inputs, outputs);

